    """
    Los datos previos eran compartidos: pasan a un administrador. Los mensajes
    de campaña van al dueño de la campaña. Sin administrador quedan sin dueño,
    es decir, visibles solo para staff.
    """
    app_label, model_name = settings.AUTH_USER_MODEL.split('.')
    User = apps.get_model(app_label, model_name)
    Contact = apps.get_model('mass_sender', 'Contact')
    Message = apps.get_model('mass_sender', 'Message')

    admin = (
        User.objects.filter(is_superuser=True).order_by('id').first()
        or User.objects.filter(is_staff=True).order_by('id').first()
    )
    for message in Message.objects.filter(campaign__owner__isnull=False).select_related('campaign'):
        Message.objects.filter(pk=message.pk).update(owner_id=message.campaign.owner_id)
    if admin:
        Contact.objects.filter(owner__isnull=True).update(owner=admin)
        Message.objects.filter(owner__isnull=True).update(owner=admin)


